// TypeScript Version: 4.1

/**
* Computes the modified Bessel function of the second kind of order zero.
*
* ## Notes
*
* -   Accuracy for subnormal `x` is very poor. Full accuracy is achieved at approximately
*     `1.0e-308` but degrades rapidly as `x → 0`.
*
* @param x - input value
* @returns evaluated Bessel function
*
* @example
* var v = k0( 0.0 );
* // returns Infinity
*
* @example
* var v = k0( 1.0 );
* // returns ~0.421
*
* @example
* var v = k0( 5.0 );
* // returns ~0.00369
*
* @example
* var v = k0( -1.0 );
* // returns NaN
*
* @example
* var v = k0( Infinity );
* // returns 0.0
*
* @example
* var v = k0( NaN );
* // returns NaN
*/
declare function k0( x: number ): number;


// EXPORTS //

export = k0;
